      "قال النهر: هل اقتنعت الآن أنك كنت مخطئة؟",
      "قالت الشجرة: أخطأت فعلًا؛ فقد كان يفترض بي عدم نسيان المستقبل، عندما أنظر إلى الحاضر.",
